#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

int n, total, sumArr[15], answer;
vector<int> vectors[15];

void dfs1(int level, int num);
void dfs2(int x);

int main() {
    cin >> n;
    dfs1(0, 0);
    for (int i = 0; i <= 7; i++) {
        sort(vectors[i].begin(), vectors[i].end());
    }
    total = 0;
    for (int i = 1; i <= 9; i++) {
        dfs2(i);
    }
    cout << answer << "\n";
    return 0;
}

void dfs1(int level, int num) {
    if (level == 7) return;
    total++;
    int back = ((total - num) % 998244353 + 998244353) % 998244353;
    vectors[level].push_back(back);
    sumArr[level] = (sumArr[level] + back) % 1000000007;
    for (int i = 0; i <= 9; i++) {
        dfs1(level + 1, num * 10 + i);
    }
}

void dfs2(int x) {
    if (x > n) return;
    if (x * 1000000 + 999999 <= n && x * 10 * 1000000 > n) {
        int current = total;
        for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
            int sizeVec = vectors[i].size();
            int diffVal = ((current - x * mul) % 998244353 + 998244353) % 998244353;
            int pos = (int)(lower_bound(vectors[i].begin(), vectors[i].end(), 1000000000 - diffVal) - vectors[i].begin());
            answer = (answer + diffVal * sizeVec + sumArr[i]) % 1000000007;
            answer = (answer - 998244353 * (sizeVec - pos) % 1000000007 + 1000000007) % 1000000007;
            total += sizeVec;
        }
        return;
    }
    total++;
    answer = (answer + ((total - x) % 998244353 + 998244353) % 998244353) % 1000000007;
    for (int i = 0; i <= 9; i++) {
        dfs2(x * 10 + i);
    }
}
